test.fraud_analytics.assert_risk_flags.raw_code:
select 'customer' as model_name, customer_id as entity_id
from {{ ref('mart_customer_risk_profile') }}
where
    risk_level != {{ risk_level('fraud_rate') }}
    or has_known_risk != (labeled_transaction_count > 0)
    or first_transaction_at > last_transaction_at
union all
select 'merchant' as model_name, merchant as entity_id
from {{ ref('mart_merchant_analytics') }}
where
    is_suspicious != ifNull(
        labeled_transaction_count >= {{ var('suspicious_min_labeled_transactions') }}
        and fraud_rate >= {{ var('high_risk_fraud_rate') }},
        false
    )
union all
select
    'hourly' as model_name,
    concat(toString(day_of_week), ':', toString(transaction_hour)) as entity_id
from {{ ref('mart_hourly_fraud_pattern') }}
where
    is_high_risk_window != ifNull(
        labeled_transaction_count >= {{ var('suspicious_min_labeled_transactions') }}
        and fraud_rate > baseline_fraud_rate,
        false
    )

test.fraud_analytics.assert_fraud_rate_b.raw_code:
{% set marts = [
    'mart_fraud_by_category', 'mart_fraud_by_state', 'mart_customer_risk_profile',
    'mart_hourly_fraud_pattern', 'mart_merchant_analytics'
] %}

{% for mart in marts %}
select
    '{{ mart }}' as model_name,
    fraud_rate,
    fraud_count,
    labeled_transaction_count
from {{ ref(mart) }}
where
    fraud_rate < 0
    or fraud_rate > 100
    or fraud_count > labeled_transaction_count
    or labeled_transaction_count > transaction_count
    or (labeled_transaction_count = 0 and fraud_rate is not null)
    or (labeled_transaction_count > 0 and fraud_rate is null)
    or abs(
        ifNull(fraud_rate, 0)
        - ifNull(100.0 * fraud_count / nullIf(labeled_transaction_count, 0), 0)
    ) > 0.000001
{% if not loop.last %}
union all
{% endif %}
{% endfor %}

test.fraud_analytics.assert_marts_reconc.raw_code:
{% set marts = [
    'mart_daily_state_metrics', 'mart_fraud_by_category', 'mart_fraud_by_state',
    'mart_customer_risk_profile', 'mart_hourly_fraud_pattern', 'mart_merchant_analytics'
] %}

with staging as (
    select
        count() as row_count,
        sum(amount) as total_amount,
        countIf(is_labeled) as labeled_count,
        countIf(is_fraud = 1) as fraud_count,
        sumIf(amount, is_fraud = 1) as fraud_amount
    from {{ ref('stg_transactions') }}
)

{% for mart in marts %}
select '{{ mart }}' as model_name
from (
    select
        sum(transaction_count) as row_count,
        sum(total_amount) as total_amount{% if mart != 'mart_daily_state_metrics' %},
            sum(labeled_transaction_count) as labeled_count,
            sum(fraud_count) as fraud_count,
            sum(fraud_amount) as fraud_amount
        {% endif %}
    from {{ ref(mart) }}
) as m
cross join staging as s
where
    m.row_count != s.row_count
    or m.total_amount != s.total_amount
    {% if mart != 'mart_daily_state_metrics' %}
        or m.labeled_count != s.labeled_count
        or m.fraud_count != s.fraud_count
        or m.fraud_amount != s.fraud_amount
    {% endif %}
{% if not loop.last %}
union all
{% endif %}
{% endfor %}

